INSERT INTO testimonials (id,name,role,text,rating,created_at,updated_at) VALUES ('57ea8b8e-75c2-47ed-b011-36c64980928e','Mr. Gogoua','Proprietaire','Depuis que je collabore avec Safe Trip, mon appartement est régulièrement loué par des clients sérieux. Leur gestion est transparente et me fait gagner un temps précieux !!!\n',5,1782386192076,NULL);
INSERT INTO testimonials (id,name,role,text,rating,created_at,updated_at) VALUES ('0d370c3d-5cbb-4937-9b61-30a44c17ab07','Daril','Client','Je voyage souvent pour le travail et Safe Trip m’a permis de réserver un studio propre et conforme à mes attentes. Leur équipe est à l’écoute et très professionnelle.\n',4,1782386227383,NULL);
INSERT INTO testimonials (id,name,role,text,rating,created_at,updated_at) VALUES ('7efaccf4-ef92-44ab-93a5-3e68672a14dc','Mr. Toumba','Propriétaire','Safe Trip m’apporte une visibilité que je n’avais jamais eue auparavant pour ma villa. Les échanges sont fluides et les locataires envoyés sont toujours respectueux.\n',5,1782386288557,NULL);
INSERT INTO testimonials (id,name,role,text,rating,created_at,updated_at) VALUES ('eeab7c1b-9458-47b4-9884-d51be46c423d','Perplexe','Client','Grâce à Safe Trip, j’ai enfin trouvé une résidence sécurisée à Abidjan sans stress ni mauvaise surprise. Le service est rapide, fiable et vraiment rassurant !!!',5,1782386327565,NULL);
